B.Ph=new A.aa(983412,"MaterialIcons",!0)
B.aZB=new A.kp(B.Ph,"Grafik i\xe7in en az 2 sonu\xe7 gerek","Deneme \xe7\xf6zd\xfck\xe7e ya da d\u0131\u015f deneme girdik\xe7e net \xe7izgin burada \u015fekillenecek. \u0130lk noktay\u0131 koymak sende!",null)
B.P4=new A.aa(63507,"MaterialIcons",!1)
B.aZC=new A.kp(B.P4,"Bu derste konu yok","Konular eklendi\u011finde burada g\xf6r\xfcnecek. \u015eimdilik dersin tamam\u0131ndan soru gelsin.",null)
B.aZD=new A.kp(B.kL,"Hen\xfcz yar\u0131\u015fmad\u0131n","\u0130lk yar\u0131\u015f\u0131n\u0131 tamamlad\u0131\u011f\u0131nda sonu\xe7lar\u0131n burada birikmeye ba\u015flar.",null)
B.OU=new A.aa(63023,"MaterialIcons",!1)
B.aZE=new A.kp(B.OU,"Ko\xe7un haz\u0131rlan\u0131yor",'Yak\u0131nda buradan "Bug\xfcn ne \xe7al\u0131\u015fay\u0131m?", "2 saatim var" ya da "Hedefime yeti\u015fir miyim?" diye sorabileceksin. Cevaplar tahmine de\u011fil, senin \xe7\xf6zd\xfc\u011f\xfcn sorulara dayanacak.',null)
B.aZG=new A.kp(B.P4,"Bug\xfcn i\xe7in g\xf6rev \xfcretemedim","Yay\u0131nda yeterli soru bulunamad\u0131. \u0130\xe7erik eklendik\xe7e plan\u0131n her sabah otomatik haz\u0131rlanacak.",null)
B.ue=new A.aa(63668,"MaterialIcons",!1)
B.aZH=new A.kp(B.ue,"Hen\xfcz veri yok","Soru \xe7\xf6zmeye ba\u015flad\u0131\u011f\u0131nda ders baz\u0131ndaki do\u011fruluklar\u0131n burada \xe7ubuklar h\xe2linde belirecek.",null)
B.aZI=new A.kp(B.kL,"Zay\u0131f konu tespiti i\xe7in veri az","Bir konuda en az 4 soru \xe7\xf6z\xfcnce karnesi olu\u015fur; en d\xfc\u015f\xfck do\u011fruluklu 5 konun burada s\u0131ralan\u0131r.",null)
